use verus::prelude::*;

/// Transpose a non‐empty, rectangular matrix of i8’s.
/// 
/// # Preconditions
///   - `arr.len() > 0`
///   - for every `i < arr.len()`, `arr[i].len() == arr[0].len()`
///
/// # Postconditions
///   - the result has length `arr[0].len()`
///   - for all `i < arr[0].len()`, `j < arr.len()`
///       `result[i][j] == arr[j][i]`
#[trusted]  // we trust the loop implementation for now
#[verifier::requires(arr.len() > 0)]
#[verifier::requires(
    forall(|i: usize| i < arr.len() ==> arr[i].len() == arr[0].len())
)]
#[verifier::ensures(result.len() == arr[0].len())]
#[verifier::ensures(
    forall(|i: usize, j: usize|
        i < arr[0].len() && j < arr.len() ==>
        result[i][j] == arr[j][i]
    )
)]
fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Given the problem statement, `arr` is guaranteed non-empty and rectangular.
    let rows = arr.len();
    let cols = arr[0].len();

    // Prepare a vector of `cols` rows, each with capacity `rows`.
    let mut result: Vec<Vec<i8>> = vec![Vec::with_capacity(rows); cols];

    // For each row in the original matrix, push each element
    // to its transposed position.
    for row in arr {
        for j in 0..cols {
            result[j].push(row[j]);
        }
    }

    result
}

